'use strict';
// GENERATED BY native-session-chat-split script — do not edit manually.
// Behavior-preserving extraction from native-session-chat.js.

const fs = require('node:fs');
const { resolveNativeCliPath } = require('../runtime/native-cli-resolver');
const {
  resolveProviderCliPath,
  installNativeCliWithProgress,
  buildCliNotFoundMessage
} = require('../cli/services/ai-cli/ensure-native-cli');
const {
  readSessionMessages,
  resolveSessionFilePath,
  getRealHome
} = require('../sessions/session-reader');
const { DEFAULT_LOCAL_CLAUDE_PACKAGE_PATH, normalizeString } = require('./native-session-chat-utils');

function resolveNativeCliLaunch(provider, options = {}) {
  const normalizedProvider = normalizeString(provider).toLowerCase();
  const env = options.env || process.env;
  if (normalizedProvider === 'claude') {
    const configuredScript = normalizeString(
      options.claudeCliJsPath
      || env.AIH_CLAUDE_CLI_JS_PATH
      || process.env.AIH_CLAUDE_CLI_JS_PATH
    );
    // 显式配置的 cli.js 最优先。
    if (configuredScript && fs.existsSync(configuredScript)) {
      return { command: process.execPath, prefixArgs: [configuredScript] };
    }
    // 否则优先用 PATH 上真正安装的 claude（版本最新、能读当前 OAuth 凭据）。
    // 之前的默认值硬编码到 ~/Downloads/package/cli.js（某台机器上是旧版 2.1.88），
    // 旧版读不了新版写的凭据 → native 报 "Not logged in · Please run /login"。
    // 因此该本地下载包只作为「PATH 上找不到 claude」时的最后兜底。
    const pathClaude = resolveNativeCliPath('claude', {
      env,
      appRoot: options.appRoot,
      cwd: options.cwd,
      runtimeToolsDir: options.runtimeToolsDir,
      spawnSyncImpl: options.spawnSyncImpl
    });
    if (!pathClaude && fs.existsSync(DEFAULT_LOCAL_CLAUDE_PACKAGE_PATH)) {
      return { command: process.execPath, prefixArgs: [DEFAULT_LOCAL_CLAUDE_PACKAGE_PATH] };
    }
    // pathClaude 存在 → 落到下方通用 resolveNativeCliPath 分支返回。
  }

  // Provider id may differ from PATH binary (qodercn → qoderclicn, kiro → kiro-cli).
  let { getAiCliBinaryName } = {};
  try {
    ({ getAiCliBinaryName } = require('../cli/services/ai-cli/provider-registry'));
  } catch (_error) {
    getAiCliBinaryName = null;
  }
  const binaryName = (typeof getAiCliBinaryName === 'function'
    ? getAiCliBinaryName(normalizedProvider)
    : '') || normalizedProvider;
  const resolveOpts = {
    env,
    appRoot: options.appRoot,
    cwd: options.cwd,
    runtimeToolsDir: options.runtimeToolsDir,
    spawnSyncImpl: options.spawnSyncImpl
  };
  const providerCliPath = resolveProviderCliPath(normalizedProvider, {
    hostHomeDir: options.hostHomeDir || getRealHome(),
    appRoot: options.appRoot,
    runtimeToolsDir: options.runtimeToolsDir,
    processObj: {
      platform: process.platform,
      env,
      cwd: () => options.cwd || process.cwd()
    },
    projectFallback: true
  });
  const cliPath = providerCliPath
    || resolveNativeCliPath(binaryName, resolveOpts)
    || (binaryName !== normalizedProvider
      ? resolveNativeCliPath(normalizedProvider, resolveOpts)
      : '');
  if (!cliPath) {
    const error = new Error(`未找到 ${binaryName} CLI`);
    error.code = 'cli_not_found';
    throw error;
  }

  return {
    command: cliPath,
    prefixArgs: []
  };
}

// 会话发起前的 CLI 就绪检查:先按 spawnNativeSessionStream 实际会用的同一套解析逻辑
// （resolveNativeCliLaunch）探测一次；探测到 cli_not_found 后先执行调用方提供的安装确认，
// 确认通过才触发自动安装（installNativeCliWithProgress，与 CLI/accounts 页复用同一份 strategy registry）。
// 安装计划进度经 onProgress 回传给调用方。
// 安装成功后不需要额外回填：下游 spawnNativeSessionStream 会重新调用 resolveNativeCliLaunch，
// 届时新装的二进制已经在 PATH 上，自然解析成功。

async function ensureNativeCliReadyForChat(provider, options = {}) {
  const normalizedProvider = normalizeString(provider).toLowerCase();
  const onProgress = typeof options.onProgress === 'function' ? options.onProgress : () => {};
  try {
    resolveNativeCliLaunch(normalizedProvider, {
      claudeCliJsPath: options.claudeCliJsPath,
      env: options.env
    });
    return { ok: true, installed: false };
  } catch (error) {
    if (!error || error.code !== 'cli_not_found') throw error;
  }

  if (typeof options.confirmInstall !== 'function') {
    return {
      ok: false,
      installed: false,
      confirmationRequired: true,
      message: `安装 ${normalizedProvider} CLI 前需要用户确认`
    };
  }

  const confirmation = await options.confirmInstall({ provider: normalizedProvider });
  const confirmed = confirmation === true
    || (confirmation && confirmation.decision === 'confirm');
  if (!confirmed) {
    const message = `已取消安装 ${normalizedProvider} CLI`;
    onProgress({ installPhase: 'cancelled', message });
    return {
      ok: false,
      installed: false,
      cancelled: true,
      message
    };
  }

  onProgress({ installPhase: 'installing' });
  const outcome = await installNativeCliWithProgress(normalizedProvider, {
    ...options,
    hostHomeDir: options.hostHomeDir,
    onPlanStart: (plan) => onProgress({ installPhase: 'installing', planId: plan.id, planLabel: plan.label }),
    onPlanFinish: (attempt) => onProgress({
      installPhase: attempt.ok ? 'plan-succeeded' : 'plan-failed',
      planId: attempt.id,
      planLabel: attempt.label,
      ...(attempt.ok ? {} : { error: attempt.error })
    })
  });

  if (outcome.cliPath) {
    onProgress({ installPhase: 'installed' });
    return { ok: true, installed: true, cliPath: outcome.cliPath };
  }

  const message = buildCliNotFoundMessage(normalizedProvider, outcome);
  onProgress({ installPhase: 'failed', message });
  return { ok: false, installed: false, message, installAttempts: outcome.installAttempts };
}


module.exports = { resolveNativeCliLaunch, ensureNativeCliReadyForChat };
